--
-- Name: fn_get_category_tree(uuid); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.fn_get_category_tree(cid uuid) RETURNS TABLE(id uuid)
    LANGUAGE sql
    AS $$
    WITH RECURSIVE sub AS (
        SELECT id
        FROM categories
        WHERE id = cid

        UNION ALL

        SELECT c.id
        FROM categories c
        INNER JOIN sub s ON c.parent_id = s.id
    )
    SELECT id FROM sub;
$$;


ALTER FUNCTION public.fn_get_category_tree(cid uuid) OWNER TO admin;

--
-- Name: fn_get_related_categories_by_slug(text); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.fn_get_related_categories_by_slug(slug_input text) RETURNS TABLE(id uuid, name text, slug text, parent_id uuid, total_courses bigint)
    LANGUAGE sql
    AS $$

WITH RECURSIVE

-- 1) Category hiện tại
current AS (
    SELECT id, parent_id, slug
    FROM categories
    WHERE slug = slug_input
),

-- 2) Tìm root (chuỗi ancestor ngược)
root_cat AS (
    SELECT id, parent_id
    FROM current

    UNION ALL

    SELECT c.id, c.parent_id
    FROM categories c
    JOIN root_cat r ON r.parent_id = c.id
),

root_id AS (
    SELECT id FROM root_cat WHERE parent_id IS NULL
),

-- 3) Lấy toàn bộ subtree từ root
subtree AS (
    SELECT id, parent_id, name, slug
    FROM categories
    WHERE id = (SELECT id FROM root_id)

    UNION ALL

    SELECT c.id, c.parent_id, c.name, c.slug
    FROM categories c
    JOIN subtree s ON c.parent_id = s.id
),

-- 4) Đếm khóa học
course_count AS (
    SELECT 
        category_id AS cid,
        COUNT(*) AS total_courses
    FROM courses
    WHERE is_published = TRUE 
      AND approval_status = 'approved'
    GROUP BY category_id
)

-- 5) Output (loại category hiện tại)
SELECT 
    s.id,
    s.name,
    s.slug,
    s.parent_id,
    COALESCE(cc.total_courses, 0) AS total_courses
FROM subtree s
LEFT JOIN course_count cc ON cc.cid = s.id
WHERE s.slug <> slug_input
ORDER BY total_courses DESC, s.name ASC;   -- ⬅ ORDER ĐÚNG YÊU CẦU

$$;


ALTER FUNCTION public.fn_get_related_categories_by_slug(slug_input text) OWNER TO admin;

--
-- Name: fn_get_root_and_level1_from_slug(text); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.fn_get_root_and_level1_from_slug(cat_slug text) RETURNS TABLE(id uuid, name text, slug text, level integer)
    LANGUAGE sql
    AS $$
WITH RECURSIVE tree AS (
    -- 1) Lấy node hiện tại từ slug người dùng truyền vào
    SELECT 
        c.id,
        c.name,
        c.slug,
        c.parent_id,
        0 AS depth
    FROM categories c
    WHERE c.slug = cat_slug

    UNION ALL

    -- 2) Leo lên tới ROOT
    SELECT 
        p.id,
        p.name,
        p.slug,
        p.parent_id,
        t.depth - 1
    FROM categories p
    JOIN tree t ON t.parent_id = p.id
),

root AS (
    -- 3) Lấy root duy nhất (depth nhỏ nhất)
    SELECT *
    FROM tree
    ORDER BY depth ASC
    LIMIT 1
),

children AS (
    -- 4) Lấy các category cấp 1 (là con trực tiếp của root)
    SELECT 
        c.id,
        c.name,
        c.slug,
        1 AS level
    FROM categories c
    CROSS JOIN root r
    WHERE c.parent_id = r.id
)

-- 5) Trả về: root (level = 0) ★ và cấp 1 (level = 1)
SELECT 
    r.id,
    r.name,
    r.slug,
    0 AS level
FROM root r

UNION ALL

SELECT * FROM children;
$$;


ALTER FUNCTION public.fn_get_root_and_level1_from_slug(cat_slug text) OWNER TO admin;

--
-- Name: fn_recommend_top20(uuid); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.fn_recommend_top20(uid uuid) RETURNS TABLE(course_id uuid, course_title text, course_thumbnail text, course_slug text, instructor_id uuid, instructor_name text, instructor_avatar text, similarity double precision)
    LANGUAGE sql
    AS $$
WITH user_emb AS (
    SELECT preferences_embedding AS emb
    FROM public."user"
    WHERE id = uid
),

base AS (
    SELECT
        c.id AS course_id,
        c.title AS course_title,
        c.thumbnail_url AS course_thumbnail,
        c.slug AS course_slug,
        c.instructor_id,
        (1 - cosine_distance(c.embedding, u.emb)) AS sim
    FROM courses c
    CROSS JOIN user_emb u
    WHERE 
        c.embedding IS NOT NULL
        AND c.is_published = TRUE
        AND c.approval_status = 'approved'
        AND c.id NOT IN (
            SELECT course_id 
            FROM course_enrollments
            WHERE user_id = uid
              AND status = 'active'
        )
)

SELECT 
    b.course_id,
    b.course_title,
    b.course_thumbnail,
    b.course_slug,
    b.instructor_id,
    u.fullname AS instructor_name,
    u.avatar AS instructor_avatar,
    b.sim AS similarity
FROM base b
LEFT JOIN public."user" u ON u.id = b.instructor_id
ORDER BY b.sim DESC
LIMIT 20;
$$;


ALTER FUNCTION public.fn_recommend_top20(uid uuid) OWNER TO admin;

--
-- Name: fn_related_courses(uuid, uuid); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.fn_related_courses(uid uuid, cid uuid) RETURNS TABLE(course_id uuid, course_title text, course_thumbnail text, instructor_id uuid, instructor_name text, instructor_avatar text, views integer, enrolls integer, rating double precision, score double precision)
    LANGUAGE sql
    AS $$

WITH cat AS (
    SELECT id FROM fn_get_category_tree(cid)
),

base AS (
    SELECT
        c.id AS course_id,
        c.title AS course_title,
        c.thumbnail_url AS course_thumbnail,
        c.instructor_id,
        c.views,
        c.total_enrolls,
        c.rating_avg,
        (
            COALESCE(c.total_enrolls,0)*3
            + COALESCE(c.views,0)
            + COALESCE(c.rating_avg,0)*20
        ) AS score
    FROM courses c
    WHERE 
        c.category_id IN (SELECT id FROM cat)
        AND c.is_published = TRUE
        AND c.approval_status = 'approved'
        AND c.id NOT IN (
            SELECT course_id 
            FROM course_enrollments
            WHERE user_id = uid
              AND status = 'active'
        )
)

SELECT
    b.course_id,
    b.course_title,
    b.course_thumbnail,
    b.instructor_id,
    u.fullname AS instructor_name,
    u.avatar AS instructor_avatar,
    b.views,
    b.total_enrolls AS enrolls,
    b.rating_avg AS rating,
    b.score
FROM base b
LEFT JOIN public."user" u ON u.id = b.instructor_id
ORDER BY b.score DESC
LIMIT 10;

$$;


ALTER FUNCTION public.fn_related_courses(uid uuid, cid uuid) OWNER TO admin;

--
-- Name: rag_search_scope(uuid, text, public.vector); Type: FUNCTION; Schema: public; Owner: admin
--

CREATE FUNCTION public.rag_search_scope(p_lesson_id uuid, p_scope text, p_query_embedding public.vector) RETURNS TABLE(scope_used text, course_id uuid, course_title text, section_id uuid, section_title text, lesson_id uuid, lesson_title text, source_type text, chunk_id uuid, resource_id uuid, resource_title text, resource_type text, resource_url text, chunk_index integer, content text, similarity double precision, distance double precision)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_section_id uuid;
    v_course_id uuid;
    v_scope text;
BEGIN
    -- normalize scope
    v_scope := lower(coalesce(p_scope, 'lesson'));
    IF v_scope NOT IN ('lesson','section','course') THEN
        v_scope := 'lesson';
    END IF;

    -- lấy section_id và course_id từ lesson hiện tại
    SELECT l.section_id, l.course_id INTO v_section_id, v_course_id
    FROM public.lessons l
    WHERE l.id = p_lesson_id;

    RETURN QUERY
    WITH target_lessons AS (
        SELECT l2.id AS lesson_id
        FROM public.lessons l2
        WHERE (v_scope = 'lesson' AND l2.id = p_lesson_id)
           OR (v_scope = 'section' AND v_section_id IS NOT NULL AND l2.section_id = v_section_id)
           OR (v_scope = 'course' AND v_course_id IS NOT NULL AND l2.course_id = v_course_id)
    ),
    ranked AS (
        -- 1) lesson_chunks (video / transcript)
        SELECT
            v_scope AS _scope_used,
            c.id AS _course_id,
            c.title AS _course_title,
            s.id AS _section_id,
            s.title AS _section_title,
            l.id AS _lesson_id,
            l.title AS _lesson_title,
            'lesson'::text AS _source_type,
            lc.id AS _chunk_id,
            NULL::uuid AS _resource_id,
            NULL::text AS _resource_title,
            NULL::text AS _resource_type,
            NULL::text AS _resource_url,
            lc.chunk_index AS _chunk_index,
            lc."text" AS _content,
            1 - (lc.embedding <=> p_query_embedding) AS _similarity,
            (lc.embedding <=> p_query_embedding) AS _distance
        FROM public.lesson_chunks lc
        JOIN target_lessons tl ON tl.lesson_id = lc.lesson_id
        JOIN public.lessons l ON l.id = lc.lesson_id
        LEFT JOIN public.courses c ON c.id = l.course_id
        LEFT JOIN public.course_sections s ON s.id = l.section_id
        
        UNION ALL
        
        -- 2) resource_chunks (tài liệu)
        SELECT
            v_scope AS _scope_used,
            c.id AS _course_id,
            c.title AS _course_title,
            s.id AS _section_id,
            s.title AS _section_title,
            l.id AS _lesson_id,
            l.title AS _lesson_title,
            'resource'::text AS _source_type,
            rc.id AS _chunk_id,
            rc.resource_id AS _resource_id,
            lr.title AS _resource_title,
            lr.resource_type AS _resource_type,
            lr.url AS _resource_url,
            rc.chunk_index AS _chunk_index,
            rc.content AS _content,
            1 - (rc.embedding <=> p_query_embedding) AS _similarity,
            (rc.embedding <=> p_query_embedding) AS _distance
        FROM public.resource_chunks rc
        JOIN target_lessons tl ON tl.lesson_id = rc.lesson_id
        JOIN public.lessons l ON l.id = rc.lesson_id
        LEFT JOIN public.courses c ON c.id = l.course_id
        LEFT JOIN public.course_sections s ON s.id = l.section_id
        LEFT JOIN public.lesson_resources lr ON lr.id = rc.resource_id
    )
    SELECT
        _scope_used AS scope_used,
        _course_id AS course_id,
        _course_title AS course_title,
        _section_id AS section_id,
        _section_title AS section_title,
        _lesson_id AS lesson_id,
        _lesson_title AS lesson_title,
        _source_type AS source_type,
        _chunk_id AS chunk_id,
        _resource_id AS resource_id,
        _resource_title AS resource_title,
        _resource_type AS resource_type,
        _resource_url AS resource_url,
        _chunk_index AS chunk_index,
        _content AS content,
        _similarity AS similarity,
        _distance AS distance
    FROM ranked
    WHERE _similarity >= 0.7
    ORDER BY _similarity DESC
    LIMIT 3;
END;
$$;


ALTER FUNCTION public.rag_search_scope(p_lesson_id uuid, p_scope text, p_query_embedding public.vector) OWNER TO admin;

