.	[0.012684646,0.015262892,0.021834517,-0.08663774,-0.0038032392,0.017483354,-0.022476824,0.001974177,-0.0036146636,0.018565062,-0.003253286,0.0022910857,0.025706887,0.047572475,0.22804037,0.0024480526,0.022781467,0.048826072,-0.0013626128,-0.012777476,0.020069053,-0.00021388127,-0.024753872,-0.015266766,-0.013564917,-0.023954868,0.0012563872,0.018418103,0.0274318,-0.029925616,0.001199733,0.03713028,0.042140458,-0.0052974382,-0.010029643,0.011939676,0.027486015,-0.0022396874,-0.008874809,0.03151324,0.0014153814,0.0016027293,-0.0021636502,-0.02602506,0.014477376,0.004129516,-0.02438149,-0.025795918,0.010248559,0.020667985,-0.0044841566,-0.015936848,-0.010118334,-0.28560787,0.031581096,0.0065317894,-0.0070348545,-0.010218923,0.023171272,0.0008016668,-0.049890563,0.02395139,-0.04586223,-0.009686891,0.012308819,0.013521397,0.022515018,0.021584662,-0.02307568,0.0050208946,0.013841121,-0.009435048,-0.014288769,-0.0074990345,-0.009380087,-0.039605208,-0.017028872,0.017466865,0.0025823975,0.03417361,-0.04602628,-0.01041972,-0.02915534,-0.04413023,0.010617935,0.009010165,-0.03273684,0.020772455,0.015284507,0.040625792,-0.017720494,0.0031394185,-0.01811111,-0.005293521,0.025491204,-0.014651927,-0.007758692,-0.011669885,0.017566996,0.019559816,-0.010588733,-0.038516738,-0.0052624084,0.003198099,-0.023585092,0.0016477791,0.0061924844,-0.03151803,0.03595334,-0.008919601,-0.0027645163,-0.0053037675,-0.0071428213,0.016438276,0.0056377733,-0.2735604,0.013810547,0.010463819,0.008093066,0.020311324,0.0075692013,-0.00078158994,0.019221583,-0.009183582,-0.004042389,-0.007447873,-0.020109365,0.0004436589,0.0038588045,-0.008505177,-0.0085826125,-0.008001411,0.019267468,0.031092718,-0.0047636935,0.025353266,-0.020542165,0.018562842,-0.02701249,-0.01757652,-0.01669949,0.01852949,0.009229394,0.003696611,0.0028081078,-0.003650538,-0.043581497,0.011985833,-0.02528553,-0.01156632,0.021220433,0.009004824,-0.0058713546,0.034218248,0.026410619,-0.06907658,-0.019282857,-0.0087981885,-0.005438033,0